command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0"
$candidate="499f5ac4cc6810602e4def52f4e37721d111e9ba"
$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC preflight fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "UNC candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-unc-copy-move-fast-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "UNC worktree add failed"}
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "UNC diff check failed"}
  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "UNC FAST failed"}
  & .\app\winui\helper\build.cmd Debug
  if($LASTEXITCODE -ne 0){throw "UNC helper Debug build failed"}
  & .\tests\winui\m22\build.cmd Debug
  if($LASTEXITCODE -ne 0){throw "UNC M22 Debug build failed"}
  $env:FLY_M22_CONFIG="Debug"
  $env:FLY_M22_LOOPBACK_ADMIN_SHARE="YES"
  & python -X utf8 .\tests\winui\m22\test_native.py
  if($LASTEXITCODE -ne 0){throw "UNC M22 Debug native failed"}
  Write-Host "UNC_COPY_MOVE_DIFF_CHECK=PASS"
  Write-Host "UNC_COPY_MOVE_FAST=PASS"
  Write-Host "UNC_COPY_MOVE_HELPER_DEBUG_BUILD=PASS"
  Write-Host "UNC_COPY_MOVE_M22_DEBUG=PASS"
}finally{
  Remove-Item Env:FLY_M22_CONFIG -ErrorAction SilentlyContinue
  Remove-Item Env:FLY_M22_LOOPBACK_ADMIN_SHARE -ErrorAction SilentlyContinue
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
